(() => {
  "use strict";
  const API = "/api/mantenimiento";
  const $ = (s, r = document) => r.querySelector(s);
  const esc = (v) => SMG.escapeHtml(v ?? "");
  const state = { tab: "panel", opciones: null, resumen: null, data: {}, filtro: "", otId: null, busy: false };
  const main = $("#contenido");
  const dialogRoot = $("#mt-dialog-root");
  const query = (obj = {}) => new URLSearchParams(Object.entries(obj).filter(([,v]) => v !== "" && v != null)).toString();
  const fmt = (v) => Number(v || 0).toLocaleString("es-AR", { maximumFractionDigits: 2 });
  const fecha = (v) => SMG.fmtDiaHora(v || "");
  const badge = (v) => {
    const x = String(v || "—");
    const cls = /URGENTE|VENCIDO|NO_APTO|MALO|EXCEDE|ANULADA/.test(x) ? "danger" : /PROXIMO|ESPERA|REVISION|REGULAR|REVISAR/.test(x) ? "warning" : /OPERATIVO|FINALIZADA|APTO|AL_DIA|BUENO|VIGENTE/.test(x) ? "success" : "";
    return `<span class="mt-badge ${cls}">${esc(x.replaceAll("_", " "))}</span>`;
  };
  const btn = (label, act, cls = "btn", attrs = "") => `<button type="button" class="${cls}" data-act="${act}" ${attrs}>${label}</button>`;
  const empty = (msg = "No hay registros para mostrar.") => `<div class="mt-empty">${esc(msg)}</div>`;
  const table = (heads, rows) => rows.length ? `<div class="mt-table-wrap"><table class="mt-table"><thead><tr>${heads.map(x=>`<th>${x}</th>`).join("")}</tr></thead><tbody>${rows.join("")}</tbody></table></div>` : empty();
  async function api(path, options = {}) {
    const res = await fetch(API + path, { credentials: "same-origin", ...options, headers: { ...(options.body && !(options.body instanceof FormData) ? {"Content-Type":"application/json"} : {}), ...(options.headers || {}) } });
    if (res.redirected && new URL(res.url, location.href).pathname === "/login") throw new Error("La sesión venció. Inicia sesión nuevamente y vuelve a abrir Mantenimiento.");
    if (!res.ok) { let msg = `Error ${res.status}`; try { const d = await res.json(); msg = d.detail || d.message || msg; } catch {} throw new Error(msg); }
    if (res.headers.get("content-type")?.includes("application/json")) return res.json();
    throw new Error("El servidor no devolvió datos del módulo. Comprueba tu sesión y vuelve a cargar la página.");
  }
  const post = (path, body) => api(path, { method:"POST", body: JSON.stringify(body) });
  const put = (path, body) => api(path, { method:"PUT", body: JSON.stringify(body) });
  async function loadOptions() { if (!state.opciones) state.opciones = await api("/opciones"); return state.opciones; }
  async function loadSummary() { state.resumen = await api("/resumen"); return state.resumen; }
  function view(tab = location.hash.slice(1) || "panel") { return ["panel","novedades","ordenes","checklist","equipos","preventivo","indicadores","configuracion"].includes(tab) ? tab : "panel"; }
  function setTitle(title, sub = "") { return `<div class="mt-head"><div><h1>${title}</h1>${sub ? `<p>${sub}</p>` : ""}</div><div class="mt-actions">${btn("↻ Actualizar", "refresh")}</div></div>`; }
  function page(content) { main.innerHTML = `<div class="mt-page">${content}</div>`; }
  function optEquipo(val = "") { return `<option value="">Seleccionar equipo…</option>${(state.opciones?.equipos||[]).map(e=>`<option value="${esc(e.ci)}" ${val===e.ci?"selected":""}>${esc(e.ci)} · ${esc(e.display)}</option>`).join("")}`; }
  function optCc(val = "") { return `<option value="">Seleccionar centro…</option>${(state.opciones?.centros_costos||[]).map(c=>`<option value="${c.id}" ${String(val)===String(c.id)?"selected":""}>${esc(c.texto)}</option>`).join("")}`; }
  function optPersonal(selected = []) { return (state.opciones?.personal||[]).map(p=>`<option value="${esc(p.legajo)}" ${selected.map(String).includes(String(p.legajo))?"selected":""}>${esc(p.nombre)} · ${esc(p.legajo)}</option>`).join(""); }
  function header(title, copy, actions = "") { return `${setTitle(title, copy).replace(btn("↻ Actualizar", "refresh"), actions || btn("↻ Actualizar", "refresh"))}`; }
  function renderPanel(d) {
    const e=d.equipos||{}, p=d.preventivo||{};
    return `${header("Panel de mantenimiento", "Estado de la flota y actividad del taller")}
      <section class="mt-kpis"><article class="mt-kpi"><small>OT activas</small><strong>${fmt(d.ot_activas)}</strong><small>${fmt(d.ot_en_revision)} en revisión</small></article><article class="mt-kpi"><small>Novedades abiertas</small><strong>${fmt(d.novedades_abiertas)}</strong><small>Requieren evaluación</small></article><article class="mt-kpi"><small>Equipos operativos</small><strong>${fmt(e.OPERATIVO)}</strong><small>${fmt(e.FUNCIONAL)} funcionales · ${fmt(e.FUERA_DE_SERVICIO)} fuera de servicio</small></article><article class="mt-kpi"><small>Preventivos</small><strong>${fmt(p.vencidos)}</strong><small>${fmt(p.proximos)} próximos · ${fmt(p.lecturas_a_revisar)} lecturas a revisar</small></article></section>
      <section class="mt-cover"><div><h2>Gestión de mantenimiento</h2><p class="mt-muted">Novedades, órdenes de trabajo, inspecciones y seguimiento preventivo en un solo lugar.</p></div><div class="mt-actions">${btn("＋ Nueva novedad","new-novedad","btn btn-primary")}${btn("＋ Nueva OT","new-ot","btn")}</div></section>
      <div class="mt-grid"><section class="mt-card"><h2>Órdenes pendientes</h2><div id="mt-panel-ots">${empty("Cargando órdenes…")}</div></section><section class="mt-card"><h2>Novedades por resolver</h2><div id="mt-panel-nov">${empty("Cargando novedades…")}</div></section></div>`;
  }
  async function fillPanel() {
    const [ots, nov] = await Promise.all([api("/ordenes?estado=ACTIVAS"), api("/novedades?estado=ABIERTA")]);
    const otHost=$("#mt-panel-ots"), nvHost=$("#mt-panel-nov"); if (!otHost) return;
    otHost.innerHTML=ots.slice(0,7).map(o=>`<div class="mt-rowcard"><div><a class="mt-link" data-act="ot-open" data-id="${o.id}">${esc(o.numero)} · ${esc(o.titulo)}</a><p>${esc(o.objetivo)} · ${esc(o.estado.replaceAll("_"," "))}</p></div>${badge(o.prioridad)}</div>`).join("")||empty();
    nvHost.innerHTML=nov.slice(0,7).map(n=>`<div class="mt-rowcard"><div><a class="mt-link" data-act="nov-open" data-id="${n.id}">#${n.id} · ${esc(n.ci)}</a><p>${esc(n.descripcion)}</p></div>${badge(n.prioridad)}</div>`).join("")||empty();
  }
  async function renderNovedades() {
    const [rows, o] = await Promise.all([api("/novedades?estado="+(state.data.novEstado||"PENDIENTES")),loadOptions()]); state.data.novedades=rows;
    const rs=rows.map(n=>`<tr><td><a class="mt-link" data-act="nov-open" data-id="${n.id}">#${n.id}</a></td><td>${esc(n.ci||n.objetivo)}<p>${esc(n.objetivo||"")}</p></td><td>${esc(n.descripcion)}</td><td>${badge(n.prioridad)}</td><td>${badge(n.estado)}</td><td>${fecha(n.creada_en)}</td><td>${n.ot_numero?`<a class="mt-link" data-act="ot-open" data-id="${n.ot_id}">${n.informe_url?`Ver Informe OT Nº${esc(n.ot_numero)} - ${esc(n.ci||"")}`:esc(n.ot_numero)}</a>`:"—"}</td></tr>`);
    page(`${header("Novedades", "Reportes de fallas y observaciones de los equipos", btn("＋ Cargar novedad","new-novedad","btn btn-primary"))}<section class="mt-card"><div class="mt-toolbar"><label>Estado<select id="nov-estado"><option value="PENDIENTES">Pendientes</option><option value="ABIERTA">Abiertas</option><option value="EN_OT">En OT</option><option value="CERRADA">Cerradas</option><option value="TODAS">Todas</option></select></label><label>Equipo<select id="nov-ci"><option value="">Todos los equipos</option>${o.equipos.map(e=>`<option>${esc(e.ci)}</option>`).join("")}</select></label><button class="btn" data-act="nov-filter">Filtrar</button></div>${table(["N°","Equipo","Descripción","Prioridad","Estado","Reportada","OT"],rs)}</section>`);
    $("#nov-estado").value=state.data.novEstado||"PENDIENTES";
  }
  async function renderOrdenes() {
    const rows=await api("/ordenes?estado="+(state.data.otEstado||"ACTIVAS")); state.data.ordenes=rows;
    const rs=rows.map(o=>`<tr><td><a class="mt-link" data-act="ot-open" data-id="${o.id}">${esc(o.numero)}</a></td><td>${esc(o.titulo)}<p>${esc(o.descripcion||"")}</p></td><td>${esc(o.objetivo)}</td><td>${badge(o.estado)}</td><td>${badge(o.prioridad)}</td><td>${(o.mecanicos||[]).map(m=>esc(m.nombre)).join(", ")||"—"}</td><td>${fmt(o.horas)} h</td><td>${o.estado==="FINALIZADA"?`<a class="mt-link" href="${API}/ordenes/${o.id}/informe" target="_blank">Ver informe ${esc(o.numero)}</a>`:""}</td></tr>`);
    page(`${header("Órdenes de trabajo", "Seguimiento del trabajo, personal, tiempos y repuestos", btn("＋ Crear OT","new-ot","btn btn-primary"))}<section class="mt-card"><div class="mt-toolbar"><label>Estado<select id="ot-estado"><option value="ACTIVAS">Activas</option><option value="EN_REVISION">En revisión</option><option value="FINALIZADA">Finalizadas</option><option value="ANULADA">Anuladas</option><option value="TODAS">Todas</option></select></label><button class="btn" data-act="ot-filter">Filtrar</button></div>${table(["OT","Trabajo","Equipo / centro","Estado","Prioridad","Mecánicos","Horas","Informe"],rs)}</section>`);
    $("#ot-estado").value=state.data.otEstado||"ACTIVAS";
  }
  async function openOrden(id, {push=true} = {}) {
    closeDialog(); state.otId=id; const d=await api(`/ordenes/${id}`);
    const ruta=`/mantenimiento/ot/${encodeURIComponent(d.numero)}`;
    if(push && location.pathname!==ruta) history.pushState({},"",ruta);
    const active=!['FINALIZADA','ANULADA'].includes(d.estado);
    const ev=(d.eventos||[]).map(e=>`<div class="mt-event"><small>${fecha(e.creado_en)} · ${esc(e.autor)} · ${esc(e.tipo)}</small><div>${esc(e.texto)}</div></div>`).join("")||empty();
    const photos=(d.fotos||[]).map(f=>`<a class="mt-photo" href="${API}/fotos/${f.id}" target="_blank"><img loading="lazy" src="${API}/fotos/${f.id}" alt="Foto OT"><small>${fecha(f.subida_en)} · ${esc(f.subida_por)}</small></a>`).join("")||empty("Sin fotos adjuntas.");
    const parts=(d.repuestos||[]).map(r=>`<tr><td>${esc(r.codigo||"—")}</td><td>${esc(r.descripcion)}<p>${esc(r.referencia||"")}</p></td><td>${fmt(r.cantidad)} ${esc(r.unidad||"")}</td><td>${r.costo_unitario==null?"—":fmt(r.cantidad*r.costo_unitario)}</td><td>${esc(r.remito_numero||"")}</td><td>${active?btn("Quitar","part-del","btn btn-danger","data-id="+r.id):""}</td></tr>`);
    const times=(d.tiempos||[]).map(t=>`<tr><td>${esc(t.nombre)}</td><td>${esc(t.legajo)}</td><td>${fecha(t.inicio)}</td><td>${t.fin?fecha(t.fin):"En curso"}</td><td>${fmt((t.minutos||0)/60)} h</td></tr>`);
    const tasks=(d.tareas_estado||[]).map((t,i)=>`<div class="mt-rowcard"><label><input type="checkbox" data-task="${i}" ${t.hecha?"checked":""} ${active?"":"disabled"}> ${esc(t.texto)}</label><small>${t.hecha?esc(t.hecha_por||"")+" · "+fecha(t.hecha_en):"Pendiente"}</small></div>`).join("");
    page(`${header(`${esc(d.numero)} · ${esc(d.titulo)}`, `${esc(d.objetivo)} · creada ${fecha(d.creada_en)}`, `${d.estado==="FINALIZADA"?`<a class="btn btn-primary" href="${API}/ordenes/${id}/informe" target="_blank">Descargar informe PDF</a>`:""}${btn("← Órdenes","back-orders","btn")}`)}<div class="mt-stats">${badge(d.estado)}${badge(d.prioridad)}<span>${fmt(d.horas)} horas</span><span>${esc(d.tipo||"CORRECTIVA")}</span></div><div class="mt-detail"><div class="mt-page"><section class="mt-card"><h2>Información de la OT</h2><dl class="mt-dl"><div><dt>Descripción</dt><dd>${esc(d.descripcion||"—")}</dd></div><div><dt>Asignados</dt><dd>${(d.mecanicos||[]).map(m=>esc(m.nombre)+" ("+esc(m.legajo)+")").join(", ")}</dd></div><div><dt>Estado / prioridad</dt><dd>${badge(d.estado)} ${badge(d.prioridad)}</dd></div><div><dt>Creada por</dt><dd>${esc(d.creada_por)} · ${fecha(d.creada_en)}</dd></div><div><dt>Mano de obra</dt><dd>${esc(d.config?.moneda||"")} ${fmt(d.costo_mano_obra)}</dd></div><div><dt>Repuestos / total</dt><dd>${esc(d.config?.moneda||"")} ${fmt(d.costo_repuestos)} / ${esc(d.config?.moneda||"")} ${fmt(d.costo_total)}</dd></div></dl><div class="mt-actions" style="margin-top:16px">${active?btn("Asignar mecánicos","ot-mecanicos"):""}${active?btn("Agregar observación","ot-comment"):""}${active?btn("Adjuntar fotos","ot-photo"):""}${active?btn("Cargar repuesto","part-add"):""}${active&&d.ci?btn("Pedir a Almacén","part-warehouse"):""}${active?btn("Anular OT","ot-cancel","btn btn-danger"):""}${d.estado==="EN_REVISION"?btn("Devolver a taller","ot-return","btn btn-danger"):""}${d.estado!=="FINALIZADA"&&d.estado!=="ANULADA"?btn("Finalizar OT","ot-finish","btn btn-primary"):""}</div></section><section class="mt-card"><h2>Repuestos</h2>${table(["Código","Descripción","Cantidad","Costo","Remito",""],parts)}</section><section class="mt-card"><h2>Tareas planificadas</h2><div class="mt-list">${tasks||empty("Sin tareas planificadas.")}</div></section><section class="mt-card"><h2>Registro fotográfico</h2><div class="mt-photo-grid">${photos}</div></section><section class="mt-card"><h2>Eventos y observaciones</h2><div class="mt-timeline">${ev}</div></section></div><aside class="mt-page"><section class="mt-card"><h2>Registro de tiempos</h2>${table(["Mecánico","Legajo","Inicio","Fin","Duración"],times)}<p class="mt-muted">Control Tarja: ${(d.control_tarja||[]).length?`${d.control_tarja.map(t=>`${esc(t.nombre)} ${esc(t.fecha)} ${badge(t.alerta||"OK")}`).join(" · ")}`:"Sin alertas"}</p></section>${d.novedad?`<section class="mt-card"><h2>Novedad de origen</h2><p>#${d.novedad.id} · ${esc(d.novedad.descripcion)}</p></section>`:""}</aside></div>`);
    main.querySelectorAll("[data-task]").forEach(el=>el.addEventListener("change", async()=>{try{await put(`/ordenes/${id}/tareas/${el.dataset.task}`,{hecha:el.checked});SMG.toast("Tarea actualizada");}catch(e){SMG.toast(e.message,"error");el.checked=!el.checked;}}));
  }
  async function renderEquipos() {
    const rows=await api("/equipos"); state.data.equipos=rows;
    const rs=rows.map(e=>`<tr><td><a class="mt-link" data-act="eq-open" data-ci="${esc(e.ci)}">${esc(e.ci)}</a><p>${esc(e.display)}</p></td><td>${esc(e.tipo||"—")}</td><td>${badge(e.estado)}</td><td>${esc(e.ubicacion||"—")}</td><td>${e.hs==null?"—":fmt(e.hs)+" h"} · ${e.km==null?"—":fmt(e.km)+" km"}</td><td>${fmt(e.novedades_abiertas)}</td><td>${fmt(e.ot_activas)}</td><td>${e.dias_sin_parte==null?"—":fmt(e.dias_sin_parte)+" días"}</td></tr>`);
    page(`${header("Equipos", "Estado actual, ubicación y actividad reciente de la flota") }<section class="mt-card"><div class="mt-toolbar"><label>Buscar equipo<input id="eq-search" placeholder="CI o descripción"></label></div>${table(["Equipo","Tipo","Estado","Ubicación","Lecturas","Novedades","OT activas","Sin parte"],rs)}</section>`);
    $("#eq-search").addEventListener("input",e=>main.querySelectorAll("tbody tr").forEach(tr=>tr.hidden=!tr.innerText.toLocaleLowerCase("es").includes(e.target.value.toLocaleLowerCase("es"))));
  }
  async function openEquipo(ci) {
    const d=await api(`/equipos/${encodeURIComponent(ci)}`), e=d.equipo;
    const changes=(d.cambios||[]).map(c=>`<tr><td>${fecha(c.creado_en)}</td><td>${esc(c.campo)}</td><td>${esc(c.anterior||"—")} → ${esc(c.nuevo)}</td><td>${esc(c.motivo||"")}</td><td>${esc(c.usuario)}</td></tr>`);
    const ots=(d.ordenes||[]).map(o=>`<tr><td><a class="mt-link" data-act="ot-open" data-id="${o.id}">${esc(o.numero)}</a></td><td>${esc(o.titulo)}</td><td>${badge(o.estado)}</td><td>${fecha(o.creada_en)}</td></tr>`);
    const nov=(d.novedades||[]).map(n=>`<tr><td>#${n.id}</td><td>${esc(n.descripcion)}</td><td>${badge(n.estado)}</td><td>${fecha(n.creada_en)}</td></tr>`);
    page(`${header(esc(e.display), `${esc(e.ci)} · ${esc(e.tipo||"")}`,btn("← Equipos","back-equipos"))}<div class="mt-stats">${badge(e.estado)}<span>Ubicación: ${esc(e.ubicacion||"—")}</span><span>${e.hs==null?"—":fmt(e.hs)+" h"} · ${e.km==null?"—":fmt(e.km)+" km"}</span></div><section class="mt-card"><h2>Acciones del equipo</h2><div class="mt-actions">${btn("Cambiar estado","eq-state")}${btn("Cambiar ubicación","eq-location")}${btn("＋ Nueva OT","new-ot","btn btn-primary","data-ci="+esc(e.ci))}</div></section><div class="mt-grid"><section class="mt-card"><h2>Órdenes de trabajo</h2>${table(["OT","Título","Estado","Fecha"],ots)}</section><section class="mt-card"><h2>Novedades</h2>${table(["N°","Descripción","Estado","Fecha"],nov)}</section></div><section class="mt-card"><h2>Historial de equipo</h2>${table(["Fecha","Campo","Cambio","Motivo","Usuario"],changes)}</section>`);
    state.data.eq=ci;
  }
  async function renderChecklist() {
    const rows=await api("/checklist"); const ops=await loadOptions(); state.data.checklists=rows;
    const rs=rows.map(c=>`<tr><td><a class="mt-link" data-act="ck-open" data-id="${c.id}">#${c.id}</a></td><td>${fecha(c.fecha)}</td><td>${esc(c.ci)}</td><td>${esc(c.tipo_equipo)}</td><td>${esc(c.operador||"—")}</td><td>${badge(c.resultado)}</td><td>${fmt(c.malos)} / ${fmt(c.total_items)}</td></tr>`);
    page(`${header("Check list", "Inspecciones por tipo de equipo y generación de novedades a partir de hallazgos",btn("＋ Realizar check list","ck-new","btn btn-primary"))}<section class="mt-card"><div class="mt-toolbar"><label>Equipo<select id="ck-ci">${optEquipo()}</select></label><button class="btn btn-primary" data-act="ck-new">Iniciar inspección</button></div>${table(["N°","Fecha","CI","Tipo","Operador","Resultado","Hallazgos / ítems"],rs)}</section>`);
  }
  async function openChecklist(id) {
    const d=await api(`/checklist/${id}`), rows=(d.respuestas||[]).map(r=>`<tr><td>${esc(r.modulo)}</td><td>${esc(r.item)}</td><td>${badge(r.valor)}</td><td>${esc(r.comentario||"—")}</td><td>${r.tiene_foto?`<a target="_blank" href="${API}/checklist/respuestas/${r.id}/foto">Ver foto</a>`:"—"}</td></tr>`);
    page(`${header(`Check list #${d.id}`, `${esc(d.ci)} · ${fecha(d.creado_en)}`,btn("← Check list","back-checklist"))}<div class="mt-stats">${badge(d.resultado)}<span>${esc(d.operador||"Sin operador")}</span><span>${d.horometro==null?"—":fmt(d.horometro)+" h"} · ${d.km==null?"—":fmt(d.km)+" km"}</span></div><section class="mt-card"><h2>Respuestas</h2>${table(["Sección","Ítem","Resultado","Observación","Foto"],rows)}<p>${esc(d.observaciones||"")}</p></section>`);
  }
  async function newChecklist(ci) {
    if(!ci) { ci=$("#ck-ci")?.value; if(!ci){SMG.toast("Seleccioná un equipo","error");return;} }
    const d=await api(`/checklist/armar/${encodeURIComponent(ci)}`);
    const sections=d.secciones.map(s=>`<div class="mt-card"><h3>${esc(s.modulo)}</h3>${s.items.map(it=>`<div class="mt-check-row"><span>${esc(it.texto)}${it.critico?' <b class="mt-muted">· Crítico</b>':''}${it.foto_obligatoria?' <b class="mt-muted">· Foto</b>':''}</span><select data-ck-value="${esc(it.clave)}"><option value="">Responder…</option>${(it.tipo==="VIGENCIA"?["VIGENTE","VENCIDA","NA"]:["BUENO","REGULAR","MALO","NA"]).map(v=>`<option value="${v}" ${v==="NA"&&!it.opcional?"disabled":""}>${v}</option>`).join("")}</select><input data-ck-comment="${esc(it.clave)}" placeholder="Observación / comentario"><input type="file" accept="image/jpeg,image/png" data-ck-photo="${esc(it.clave)}"></div>`).join("")}</div>`).join("");
    dialog(`<form id="ck-form"><div class="mt-dialog-head"><div><h2>Check list · ${esc(d.ci)}</h2><p class="mt-muted">${esc(d.display)} · ${esc(d.tipo_equipo)} · ${esc(d.ubicacion||"Sin ubicación")}</p></div><button type="button" class="btn" data-act="dialog-close">Cerrar</button></div><div class="mt-form"><label>Horómetro<input name="horometro" type="number" step="0.1" value="${d.cabecera?.horometro??""}"></label><label>Kilómetros<input name="km" type="number" step="0.1" value="${d.cabecera?.km??""}"></label><label class="wide">Operador<input name="operador" value="${esc(d.cabecera?.operador||"")}"></label><label class="wide">Observaciones<textarea name="observaciones"></textarea></label></div><div class="mt-checklist-items">${sections}</div><div class="mt-dialog-actions"><button class="btn" type="button" data-act="dialog-close">Cancelar</button><button class="btn btn-primary">Guardar inspección</button></div></form>`);
    $("#ck-form").onsubmit=async ev=>{ev.preventDefault();const fd=new FormData(ev.currentTarget), respuestas={};main.querySelectorAll("[data-ck-value]");dialogRoot.querySelectorAll("[data-ck-value]").forEach(sel=>{const k=sel.dataset.ckValue;respuestas[k]={valor:sel.value,comentario:dialogRoot.querySelector(`[data-ck-comment="${CSS.escape(k)}"]`)?.value||""};});const body={ci:d.ci,horometro:fd.get("horometro"),km:fd.get("km"),operador:fd.get("operador"),observaciones:fd.get("observaciones"),respuestas};const upload=new FormData();upload.append("datos",JSON.stringify(body));dialogRoot.querySelectorAll("[data-ck-photo]").forEach(input=>{if(input.files[0])upload.append("foto__"+input.dataset.ckPhoto,input.files[0]);});try{const saved=await api("/checklist",{method:"POST",body:upload});closeDialog();SMG.toast(`Check list #${saved.id} guardado`);await openChecklist(saved.id);}catch(e){SMG.toast(e.message,"error");}};
  }
  async function renderPreventivo() {
    const [rows, plans, obs]=await Promise.all([api("/preventivo"),api("/preventivo/planes"),api("/preventivo/lecturas")]); state.data.prev=rows;state.data.plans=plans;state.data.obs=obs;
    const rs=rows.map(a=>`<tr><td><a class="mt-link" data-act="prev-detail" data-id="${a.id}">${esc(a.ci)}</a><p>${esc(a.display)}</p></td><td>${esc(a.plan)}</td><td>${badge(a.estado)}</td><td>${a.vence_por?`${esc(a.vence_por)} · ${a.restante==null?"—":fmt(a.restante)}`:"—"}</td><td>${a.ot?`<a class="mt-link" data-act="ot-open" data-id="${a.ot.id}">${esc(a.ot.numero)}</a>`:"—"}</td><td>${btn("Acciones","prev-actions","btn","data-id="+a.id)}</td></tr>`);
    const ps=plans.map(p=>`<div class="mt-rowcard"><div><b>${esc(p.nombre)}</b><p>${esc(p.descripcion||"")} · ${p.equipos} equipos · ${[p.intervalo_hs&&`${p.intervalo_hs} h`,p.intervalo_km&&`${p.intervalo_km} km`,p.intervalo_dias&&`${p.intervalo_dias} días`].filter(Boolean).join(" / ")}</p></div><div class="mt-actions">${btn("Asignar equipos","prev-assign","btn","data-id="+p.id)}${btn("Editar","prev-edit","btn","data-id="+p.id)}</div></div>`).join("");
    page(`${header("Mantenimiento preventivo", "Planes por horas, kilómetros o días; vence el primero que se cumpla",btn("＋ Crear plan","prev-new","btn btn-primary"))}<section class="mt-kpis"><article class="mt-kpi"><small>Equipos planificados</small><strong>${rows.length}</strong></article><article class="mt-kpi"><small>Vencidos</small><strong>${rows.filter(x=>x.estado==="VENCIDO").length}</strong></article><article class="mt-kpi"><small>Próximos</small><strong>${rows.filter(x=>x.estado==="PROXIMO").length}</strong></article><article class="mt-kpi"><small>Lecturas observadas</small><strong>${obs.length}</strong></article></section><section class="mt-card"><h2>Estado de equipos</h2>${table(["Equipo","Plan","Estado","Vence por","OT preventiva",""],rs)}</section><div class="mt-grid"><section class="mt-card"><h2>Planes</h2><div class="mt-list">${ps||empty("Todavía no hay planes.")}</div></section><section class="mt-card"><h2>Lecturas a revisar</h2>${obs.length?obs.map(x=>`<div class="mt-rowcard"><div><b>${esc(x.ci)} · ${fecha(x.creado_en)}</b><p>${esc(x.motivo||x.observacion||JSON.stringify(x.avisos||""))}</p></div>${btn("Marcar revisada","prev-review","btn","data-id="+x.id)}</div>`).join(""):empty("Sin lecturas observadas")}</section></div>`);
  }
  async function prevDetail(id) {
    const d=await api(`/preventivo/asignaciones/${id}`);const tareas=(d.tareas||[]).map((t,i)=>`${i+1}. ${esc(t)}`).join("<br>");
    dialog(`<div class="mt-dialog-head"><div><h2>${esc(d.ci)} · ${esc(d.plan)}</h2><p class="mt-muted">${badge(d.estado)} ${esc(d.display)}</p></div><button class="btn" data-act="dialog-close">Cerrar</button></div><dl class="mt-dl"><div><dt>Lectura actual</dt><dd>${d.lectura?.hs??"—"} h · ${d.lectura?.km??"—"} km</dd></div><div><dt>Base service</dt><dd>${d.base_hs??"—"} h · ${d.base_km??"—"} km · ${esc(d.base_fecha)}</dd></div><div class="wide"><dt>Tareas</dt><dd>${tareas||"—"}</dd></div></dl><div class="mt-actions" style="margin-top:18px">${btn("Generar OT preventiva","prev-create-ot","btn btn-primary","data-id="+id)}${btn("Registrar service realizado","prev-done","btn","data-id="+id)}${btn("Quitar del plan","prev-remove","btn btn-danger","data-id="+id)}</div>`);
  }
  async function renderIndicadores() {
    const params=new URLSearchParams(); if(state.data.desde)params.set("desde",state.data.desde);if(state.data.hasta)params.set("hasta",state.data.hasta);
    const d=await api("/indicadores?"+params);state.data.ind=d;
    const r=d.resumen||{};
    const meses=(d.costo_mensual||[]).map(x=>`<tr><td>${esc(x.mes)}</td><td>${esc(d.moneda)} ${fmt(x.correctivo)}</td><td>${esc(d.moneda)} ${fmt(x.preventivo)}</td><td>${esc(d.moneda)} ${fmt(x.correctivo+x.preventivo)}</td></tr>`);
    const equipos=(d.costo_por_equipo||[]).map(x=>`<tr><td>${esc(x.ci)}</td><td>${esc(x.display)}</td><td>${fmt(x.ots)}</td><td>${fmt(x.horas)} h</td><td>${esc(d.moneda)} ${fmt(x.total)}</td></tr>`);
    const fallas=(d.equipos_fallas||[]).map(x=>`<tr><td>${esc(x.ci)}</td><td>${esc(x.display)}</td><td>${fmt(x.novedades)}</td><td>${fmt(x.pendientes)}</td></tr>`);
    const mecanicos=(d.mecanicos||[]).map(x=>`<tr><td>${esc(x.nombre)}</td><td>${esc(x.legajo)}</td><td>${fmt(x.horas)} h</td><td>${fmt(x.ots)}</td><td>${fmt(x.alertas)}</td></tr>`);
    page(`${header("Indicadores", "Tiempos de reparación, volumen de OT, costos y disponibilidad") }<section class="mt-card"><div class="mt-toolbar"><label>Desde<input id="ind-desde" type="date" value="${esc(state.data.desde||d.desde||"")}"></label><label>Hasta<input id="ind-hasta" type="date" value="${esc(state.data.hasta||d.hasta||"")}"></label><button class="btn btn-primary" data-act="ind-filter">Aplicar</button></div><div class="mt-muted">Período ${SMG.fmtDia(d.desde)} a ${SMG.fmtDia(d.hasta)}</div></section><section class="mt-kpis"><article class="mt-kpi"><small>OT finalizadas</small><strong>${fmt(r.ot_finalizadas)}</strong><small>${fmt(r.ot_correctivas)} correctivas · ${fmt(r.ot_preventivas)} preventivas</small></article><article class="mt-kpi"><small>Horas registradas</small><strong>${fmt(r.horas_mecanicos)}</strong><small>Promedio OT ${r.dias_medio_ot==null?"—":fmt(r.dias_medio_ot)+" días"}</small></article><article class="mt-kpi"><small>Costo total</small><strong>${esc(d.moneda)} ${fmt(r.costo_total)}</strong><small>Mano de obra ${fmt(r.costo_mano_obra)} · repuestos ${fmt(r.costo_repuestos)}</small></article><article class="mt-kpi"><small>Disponibilidad de flota</small><strong>${r.disponibilidad_flota==null?"—":fmt(r.disponibilidad_flota)+"%"}</strong><small>${fmt(r.preventivos_vencidos)} preventivos vencidos · ${fmt(r.preventivos_proximos)} próximos</small></article></section><div class="mt-grid"><section class="mt-card"><h2>Costo mensual</h2>${table(["Mes","Correctivo","Preventivo","Total"],meses)}</section><section class="mt-card"><h2>Costo por equipo</h2>${table(["CI","Equipo","OT","Horas","Costo"],equipos)}</section><section class="mt-card"><h2>Equipos con más fallas</h2>${table(["CI","Equipo","Novedades","Pendientes"],fallas)}</section><section class="mt-card"><h2>Actividad de mecánicos</h2>${table(["Mecánico","Legajo","Horas","OT","Alertas Tarja"],mecanicos)}</section><section class="mt-card"><h2>Temas frecuentes</h2>${table(["Tema","Novedades","Equipos"],(d.temas||[]).map(x=>`<tr><td>${esc(x.tema)}</td><td>${fmt(x.novedades)}</td><td>${fmt(x.equipos)}</td></tr>`))}</section></div>`);
  }
  async function renderConfig() {
    const [o,p]=await Promise.all([loadOptions(),api("/plantilla")]);state.data.plantilla=p;
    const config=o.config||{};const mods=p.modulos||[];
    const rows=mods.map(m=>`<tr><td>${esc(m.nombre)}</td><td>${esc(m.capa)}${m.familia?" · "+esc(m.familia):""}</td><td>${m.items?.length||0} ítems</td><td>${m.activo?"Activo":"Inactivo"}</td><td>${btn("＋ Ítem","ck-item-new","btn","data-id="+m.id)}</td></tr>`);
    page(`${header("Configuración", "Parámetros de costo y plantilla del check list") }<section class="mt-card"><h2>Costos</h2><form id="mt-config-form" class="mt-form"><label>Valor hora mecánico<input name="valor_hora_mecanico" type="number" min="0" step="0.01" value="${esc(config.valor_hora_mecanico||"0")}"></label><label>Moneda<input name="moneda" maxlength="10" value="${esc(config.moneda||"ARS")}"></label><div class="wide"><button class="btn btn-primary">Guardar configuración</button></div></form></section><section class="mt-card"><div class="mt-head"><h2>Plantilla del check list</h2>${btn("＋ Agregar módulo","ck-mod-new","btn btn-primary")}</div>${table(["Módulo","Capa","Contenido","Estado","Acciones"],rows)}</section>`);
    $("#mt-config-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{await put("/config",Object.fromEntries(f));SMG.toast("Configuración guardada");state.opciones=null;await renderConfig();}catch(x){SMG.toast(x.message,"error");}};
  }
  function dialog(html) { dialogRoot.innerHTML=`<div class="mt-dialog" id="mt-dialog"><div class="mt-dialog-panel">${html}</div></div>`; $("#mt-dialog").addEventListener("click",e=>{if(e.target.id==="mt-dialog")closeDialog();}); }
  function closeDialog(){dialogRoot.innerHTML="";}
  function formText(name,label,{required=false,type="text",value="",wide=false,placeholder="",step=""}={}){return `<label class="${wide?"wide":""}">${label}<input name="${name}" type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" ${required?"required":""} ${step?`step="${step}"`:""}></label>`;}
  function newNovedad() {
    dialog(`<form id="nov-form"><div class="mt-dialog-head"><div><h2>Cargar novedad</h2><p class="mt-muted">El equipo pasa a estado funcional mientras la novedad esté abierta.</p></div><button class="btn" type="button" data-act="dialog-close">Cerrar</button></div><div class="mt-form"><label class="wide">Equipo<select required name="ci">${optEquipo()}</select></label><label class="wide">Descripción<textarea name="descripcion" required maxlength="2000"></textarea></label><label>Prioridad<select name="prioridad"><option>NORMAL</option><option>URGENTE</option></select></label><label>Fotos (JPG/PNG, hasta 6)<input type="file" name="fotos" accept="image/jpeg,image/png" multiple></label></div><div class="mt-dialog-actions"><button class="btn" type="button" data-act="dialog-close">Cancelar</button><button class="btn btn-primary">Guardar novedad</button></div></form>`);
    $("#nov-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);try{const n=await post("/novedades",{tipo:"EQUIPO",ci:f.get("ci"),descripcion:f.get("descripcion"),prioridad:f.get("prioridad")});for(const file of f.getAll("fotos")){if(file.size){const up=new FormData();up.append("foto",file);await api(`/novedades/${n.id}/fotos`,{method:"POST",body:up});}}closeDialog();SMG.toast("Novedad cargada");await render();if(n.id)openNovedad(n.id);}catch(x){SMG.toast(x.message,"error");}};
  }
  async function openNovedad(id) {
    const d=await api(`/novedades/${id}`);const ph=(d.fotos||[]).map(f=>`<a class="mt-photo" target="_blank" href="${API}/fotos/${f.id}"><img src="${API}/fotos/${f.id}" alt="Foto"><small>${fecha(f.subida_en)} · ${esc(f.subida_por)}</small></a>`).join("")||empty("Sin fotos.");
    dialog(`<div class="mt-dialog-head"><div><h2>Novedad #${id} · ${esc(d.ci||d.objetivo)}</h2><p class="mt-muted">${fecha(d.creada_en)} · ${esc(d.reportada_por)}</p></div><button class="btn" data-act="dialog-close">Cerrar</button></div><div class="mt-stats">${badge(d.estado)} ${badge(d.prioridad)}<span>${esc(d.objetivo)}</span></div><section class="mt-card"><p>${esc(d.descripcion)}</p><p class="mt-muted">Confirmaciones: ${d.confirmaciones||0} · ${esc(d.resolucion||"")}</p>${d.ot_numero?`<a class="mt-link" data-act="ot-open" data-id="${d.ot_id}">${d.informe_url?`Ver Informe OT Nº${esc(d.ot_numero)} - ${esc(d.ci||"")}`:`Ver ${esc(d.ot_numero)}`}</a>`:""}</section><div class="mt-photo-grid">${ph}</div><div class="mt-actions" style="margin-top:14px">${d.estado==="ABIERTA"?btn("Resolver novedad","nov-resolve","btn btn-primary","data-id="+id):""}${btn("Adjuntar foto","nov-photo","btn","data-id="+id)}</div>`);
  }
  function newOt(prefill={}) {
    dialog(`<form id="ot-form"><div class="mt-dialog-head"><div><h2>Crear orden de trabajo</h2></div><button class="btn" type="button" data-act="dialog-close">Cerrar</button></div><div class="mt-form"><label>Equipo<select name="ci">${optEquipo(prefill.ci||"")}</select></label><label>Centro de costo<select name="centro_costo_id">${optCc()}</select></label>${formText("titulo","Título",{required:true,wide:true,max:200})}<label class="wide">Descripción<textarea name="descripcion"></textarea></label><label>Prioridad<select name="prioridad"><option>NORMAL</option><option>URGENTE</option></select></label><label class="wide">Mecánicos<select name="mecanicos" multiple size="6">${optPersonal()}</select></label></div><div class="mt-dialog-actions"><button class="btn" type="button" data-act="dialog-close">Cancelar</button><button class="btn btn-primary">Crear OT</button></div></form>`);
    $("#ot-form").onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget);const mechs=[...e.currentTarget.elements.mecanicos.selectedOptions].map(o=>o.value);try{const d=await post("/ordenes",{ci:f.get("ci"),centro_costo_id:f.get("centro_costo_id")||null,titulo:f.get("titulo"),descripcion:f.get("descripcion"),prioridad:f.get("prioridad"),mecanicos:mechs});closeDialog();SMG.toast(`Orden ${d.numero} creada`);await openOrden(d.id);}catch(x){SMG.toast(x.message,"error");}};
  }
  async function resolveNovedad(id) {
    dialog(`<form id="nov-resolve-form"><div class="mt-dialog-head"><div><h2>Resolver novedad #${id}</h2><p class="mt-muted">Crear OT o cerrar sin OT.</p></div><button type="button" class="btn" data-act="dialog-close">Cerrar</button></div><div class="mt-form"><label>Decisión<select name="decision"><option value="OT">Crear orden de trabajo</option><option value="CERRAR">Cerrar sin OT</option></select></label><label>Prioridad OT<select name="prioridad"><option>NORMAL</option><option>URGENTE</option></select></label>${formText("titulo","Título de OT",{wide:true})}<label class="wide">Descripción de OT / resolución<textarea name="descripcion"></textarea></label><label class="wide">Mecánicos<select name="mecanicos" multiple size="5">${optPersonal()}</select></label><label>Estado final del equipo<select name="estado_equipo"><option value="">Automático</option><option>OPERATIVO</option><option>FUNCIONAL</option><option>FUERA_DE_SERVICIO</option></select></label></div><div class="mt-dialog-actions"><button class="btn">Aplicar resolución</button></div></form>`);
    const form=$("#nov-resolve-form");form.elements.titulo.value="";form.elements.descripcion.value="";
    form.onsubmit=async e=>{e.preventDefault();const f=new FormData(form);const body={decision:f.get("decision"),prioridad:f.get("prioridad"),titulo:f.get("titulo"),descripcion:f.get("descripcion"),resolucion:f.get("descripcion"),mecanicos:[...form.elements.mecanicos.selectedOptions].map(o=>o.value),estado_equipo:f.get("estado_equipo")};try{const r=await post(`/novedades/${id}/resolver`,body);closeDialog();SMG.toast(r.ot?`Se creó ${r.ot.numero}`:"Novedad cerrada");if(r.ot)await openOrden(r.ot.id);else await renderNovedades();}catch(x){SMG.toast(x.message,"error");}};
  }
  function uploadPhoto(kind,id) {
    dialog(`<form id="photo-form"><div class="mt-dialog-head"><h2>Adjuntar fotografía</h2><button class="btn" type="button" data-act="dialog-close">Cerrar</button></div><label class="field">Foto JPG o PNG<input type="file" name="foto" accept="image/jpeg,image/png" required></label><div class="mt-dialog-actions"><button class="btn btn-primary">Subir foto</button></div></form>`);
    $("#photo-form").onsubmit=async e=>{e.preventDefault();const fd=new FormData(e.currentTarget);try{await api(`/${kind}/${id}/fotos`,{method:"POST",body:fd});closeDialog();SMG.toast("Foto adjuntada");kind==="ordenes"?await openOrden(id):await openNovedad(id);}catch(x){SMG.toast(x.message,"error");}};
  }
  async function render() {
    state.tab=view(); if(location.hash!=="#"+state.tab && !location.hash) history.replaceState(null,"","#panel");
    try { await loadOptions();
      const deep=location.pathname.match(/^\/mantenimiento\/ot\/([^/]+)\/?$/);
      if(deep){const rows=await api("/ordenes?estado=TODAS");const item=rows.find(o=>o.numero===decodeURIComponent(deep[1]));if(item){await openOrden(item.id,{push:false});return;}throw new Error("No se encontró la orden solicitada.");}
      if(state.tab==="panel"){const d=await loadSummary();page(renderPanel(d));fillPanel().catch(showError);}
      else if(state.tab==="novedades") await renderNovedades(); else if(state.tab==="ordenes") await renderOrdenes(); else if(state.tab==="equipos") await renderEquipos(); else if(state.tab==="checklist") await renderChecklist(); else if(state.tab==="preventivo") await renderPreventivo(); else if(state.tab==="indicadores") await renderIndicadores(); else if(state.tab==="configuracion") await renderConfig();
    } catch(e) { page(`${header("Mantenimiento", "No se pudo cargar la información") }<section class="mt-alert">${esc(e.message)}. Verifica los permisos del módulo o vuelve a iniciar sesión.</section>`); }
  }
  function showError(e){console.error("Mantenimiento:",e);if(window.SMG?.toast)SMG.toast(e.message||"No se pudo cargar Mantenimiento","error");else if(main)main.innerHTML=`<section class="mt-alert">No se pudo iniciar Mantenimiento: ${esc(e.message||"error")}</section>`;}
  async function ask(title,label,opts={}) { return SMG.pedirTexto(title,"",{etiqueta:label,multilinea:!!opts.multilinea,requerido:opts.required!==false,ok:opts.ok||"Guardar",valor:opts.value||"",peligro:!!opts.peligro}); }
  document.addEventListener("click",async e=>{
    const b=e.target.closest("[data-act]");if(!b)return;const a=b.dataset.act,id=b.dataset.id;
    try {
      if(a==="refresh"){state.opciones=null;await render();}
      else if(a==="new-novedad")newNovedad(); else if(a==="new-ot")newOt({ci:b.dataset.ci||""});
      else if(a==="nov-filter"){state.data.novEstado=$("#nov-estado").value;const ci=$("#nov-ci").value;const rows=await api("/novedades?"+query({estado:state.data.novEstado,ci}));state.data.novedades=rows;await renderNovedades();$("#nov-ci").value=ci;}
      else if(a==="ot-filter"){state.data.otEstado=$("#ot-estado").value;await renderOrdenes();}
      else if(a==="nov-open")await openNovedad(id); else if(a==="ot-open")await openOrden(id); else if(a==="eq-open")await openEquipo(b.dataset.ci); else if(a==="ck-open")await openChecklist(id);
      else if(a==="back-orders"){history.pushState({},"","/mantenimiento#ordenes");state.otId=null;await renderOrdenes();} else if(a==="back-equipos"){location.hash="#equipos";await renderEquipos();} else if(a==="back-checklist"){location.hash="#checklist";await renderChecklist();}
      else if(a==="dialog-close")closeDialog(); else if(a==="nov-resolve")await resolveNovedad(id); else if(a==="nov-photo")uploadPhoto("novedades",id); else if(a==="ot-photo")uploadPhoto("ordenes",state.otId);
      else if(a==="ck-new")await newChecklist($("#ck-ci")?.value);
      else if(a==="ot-mecanicos"){const d=await api(`/ordenes/${state.otId}`);dialog(`<form id="mechanic-form"><div class="mt-dialog-head"><h2>Asignar mecánicos</h2><button class="btn" type="button" data-act="dialog-close">Cerrar</button></div><label>Mecánicos<select name="mecanicos" multiple size="8">${optPersonal(d.mecanicos.map(x=>x.legajo))}</select></label><div class="mt-dialog-actions"><button class="btn btn-primary">Guardar asignación</button></div></form>`);$("#mechanic-form").onsubmit=async ev=>{ev.preventDefault();const legajos=[...ev.currentTarget.elements.mecanicos.selectedOptions].map(o=>o.value);try{await put(`/ordenes/${state.otId}/mecanicos`,{mecanicos:legajos});closeDialog();await openOrden(state.otId);SMG.toast("Asignación actualizada");}catch(x){showError(x);}};}
      else if(a==="ot-comment"){const text=await ask("Agregar observación","Observación",{multilinea:true});if(text){await post(`/ordenes/${state.otId}/comentario`,{texto:text});await openOrden(state.otId);}}
      else if(a==="ot-cancel"){const motivo=await ask("Anular orden","Motivo",{multilinea:true});if(motivo&&await SMG.confirmar("Anular OT","Se cerrará la orden y se detendrá el registro de tiempos.",{ok:"Anular",peligro:true})){await post(`/ordenes/${state.otId}/anular`,{motivo});await openOrden(state.otId);}}
      else if(a==="ot-return"){const observacion=await ask("Devolver al taller","Observación",{multilinea:true});if(observacion){await post(`/ordenes/${state.otId}/devolver`,{observacion});await openOrden(state.otId);}}
      else if(a==="ot-finish"){const observacion=await ask("Finalizar orden","Observaciones de cierre",{multilinea:true,required:false});if(observacion!==null){const st=await ask("Estado del equipo","Dejar el equipo en OPERATIVO, FUNCIONAL o FUERA_DE_SERVICIO",{required:false});const body={observacion,estado_equipo:st||""};const d=await post(`/ordenes/${state.otId}/finalizar`,body);SMG.toast("OT finalizada. El informe PDF quedó generado y las fotos originales se eliminaron.");await openOrden(d.id);}}
      else if(a==="part-add"){dialog(`<form id="part-form"><div class="mt-dialog-head"><h2>Agregar repuesto</h2><button class="btn" type="button" data-act="dialog-close">Cerrar</button></div><div class="mt-form">${formText("codigo","Código")}${formText("descripcion","Descripción",{required:true})}${formText("referencia","Referencia")}${formText("cantidad","Cantidad",{required:true,type:"number",step:"0.01",value:"1"})}${formText("unidad","Unidad")}${formText("costo_unitario","Costo unitario",{type:"number",step:"0.01"})}</div><div class="mt-dialog-actions"><button class="btn btn-primary">Guardar</button></div></form>`);$("#part-form").onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.currentTarget));try{await post(`/ordenes/${state.otId}/repuestos`,f);closeDialog();await openOrden(state.otId);}catch(x){showError(x);}};}
      else if(a==="part-warehouse"){dialog(`<form id="wh-form"><div class="mt-dialog-head"><div><h2>Pedir repuesto a Almacén</h2><p class="mt-muted">El pedido crea un remito pendiente de autorización.</p></div><button type="button" class="btn" data-act="dialog-close">Cerrar</button></div><div class="mt-form"><label class="wide">Buscar artículo<input id="wh-q" autocomplete="off" placeholder="Código o descripción"></label><label class="wide">Artículo<select name="producto_id" required><option value="">Escribí para buscar…</option></select></label>${formText("cantidad","Cantidad",{required:true,type:"number",step:"0.01",value:"1"})}${formText("unidad","Unidad")}${formText("costo_unitario","Costo unitario estimado",{type:"number",step:"0.01"})}<label class="wide">Números de serie (uno por línea, para artículos serializados)<textarea name="series"></textarea></label></div><div class="mt-dialog-actions"><button class="btn btn-primary">Enviar pedido</button></div></form>`);const q=$("#wh-q"),sel=$("#wh-form [name=producto_id]");let timer; q.addEventListener("input",()=>{clearTimeout(timer);timer=setTimeout(async()=>{try{const x=await api(`/ordenes/${state.otId}/repuestos/sugerencias?`+query({q:q.value}));sel.innerHTML=`<option value="">Seleccionar artículo…</option>`+(x.articulos||[]).map(p=>`<option value="${p.producto_id}">${esc(p.codigo)} · ${esc(p.descripcion)} · disponible ${fmt(p.disponible)}</option>`).join("");}catch(err){showError(err);}},240);});$("#wh-form").onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),body={producto_id:Number(f.get("producto_id")),cantidad:f.get("cantidad"),unidad:f.get("unidad"),costo_unitario:f.get("costo_unitario")||null,series:f.get("series").split(/\r?\n/).filter(Boolean)};try{await post(`/ordenes/${state.otId}/repuestos/almacen`,body);closeDialog();SMG.toast("Pedido enviado a Almacén");await openOrden(state.otId);}catch(err){showError(err);}};}
      else if(a==="part-del"){if(await SMG.confirmar("Quitar repuesto","Se eliminará este repuesto de la OT.",{ok:"Quitar",peligro:true})){await api(`/ordenes/${state.otId}/repuestos/${id}`,{method:"DELETE"});await openOrden(state.otId);}}
      else if(a==="eq-state"){const current=state.data.eq;const val=await SMG.pedirTexto("Cambiar estado",`Estado actual: ${current}. Ingresá OPERATIVO, FUNCIONAL o FUERA_DE_SERVICIO`,{etiqueta:"Nuevo estado",valor:current,requerido:true});if(val){const motivo=await ask("Motivo del cambio","Motivo",{multilinea:true});if(motivo){await put(`/equipos/${encodeURIComponent(current)}/estado`,{estado:val,motivo});await openEquipo(current);}}}
      else if(a==="eq-location"){const current=state.data.eq;const cc=await SMG.pedirTexto("Cambiar ubicación","Ingresá el ID del centro de costo",{etiqueta:"Centro de costo ID",requerido:true});if(cc){const motivo=await ask("Motivo del cambio","Motivo",{multilinea:true});if(motivo){await put(`/equipos/${encodeURIComponent(current)}/ubicacion`,{centro_costo_id:Number(cc),motivo});await openEquipo(current);}}}
      else if(a==="prev-detail")await prevDetail(id);
      else if(a==="prev-assign"){dialog(`<form id="prev-assign-form"><div class="mt-dialog-head"><h2>Asignar equipos al plan</h2><button type="button" class="btn" data-act="dialog-close">Cerrar</button></div><div class="mt-form"><label class="wide">Equipos<select name="cis" multiple size="9">${(state.opciones.equipos||[]).map(e=>`<option value="${esc(e.ci)}">${esc(e.ci)} · ${esc(e.display)}</option>`).join("")}</select></label><label>Base de última revisión<select name="base"><option value="ACTUAL">Lectura actual del último parte</option><option value="MANUAL">Ingresar manualmente</option></select></label><label>Fecha del service<input type="date" name="fecha"></label>${formText("hs","Horómetro base",{type:"number",step:"0.1"})}${formText("km","Kilómetros base",{type:"number",step:"0.1"})}</div><div class="mt-dialog-actions"><button class="btn btn-primary">Asignar equipos</button></div></form>`);const form=$("#prev-assign-form");form.onsubmit=async ev=>{ev.preventDefault();const f=new FormData(form),body={cis:[...form.elements.cis.selectedOptions].map(o=>o.value),base:f.get("base"),fecha:f.get("fecha"),hs:f.get("hs"),km:f.get("km")};try{await post(`/preventivo/planes/${id}/equipos`,body);closeDialog();await renderPreventivo();}catch(x){showError(x);}};}
      else if(a==="prev-new"||a==="prev-edit"){const plan=a==="prev-edit"?state.data.plans.find(x=>String(x.id)===String(id)):null;dialog(`<form id="plan-form"><div class="mt-dialog-head"><h2>${plan?"Editar":"Crear"} plan preventivo</h2><button class="btn" type="button" data-act="dialog-close">Cerrar</button></div><div class="mt-form">${formText("nombre","Nombre",{required:true,wide:true,value:plan?.nombre||""})}${formText("descripcion","Descripción",{wide:true,value:plan?.descripcion||""})}${formText("intervalo_hs","Intervalo horas",{type:"number",value:plan?.intervalo_hs||"",step:"0.1"})}${formText("intervalo_km","Intervalo kilómetros",{type:"number",value:plan?.intervalo_km||"",step:"0.1"})}${formText("intervalo_dias","Intervalo días",{type:"number",value:plan?.intervalo_dias||""})}${formText("aviso_pct","Aviso (%)",{type:"number",value:plan?.aviso_pct??10,step:"0.1"})}<label class="wide">Tareas (una por línea)<textarea name="tareas">${esc((plan?.tareas||[]).join("\n"))}</textarea></label><label>Activo<select name="activo"><option value="true">Sí</option><option value="false" ${plan?.activo===0?"selected":""}>No</option></select></label></div><div class="mt-dialog-actions"><button class="btn btn-primary">Guardar plan</button></div></form>`);$("#plan-form").onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),body=Object.fromEntries(f);body.activo=f.get("activo")==="true";body.tareas=f.get("tareas").split(/\r?\n/).filter(Boolean);try{await api(plan?`/preventivo/planes/${plan.id}`:"/preventivo/planes",{method:plan?"PUT":"POST",body:JSON.stringify(body)});closeDialog();await renderPreventivo();}catch(x){showError(x);}};}
      else if(a==="prev-actions"){const row=state.data.prev.find(x=>String(x.id)===String(id));if(row)await prevDetail(row.id);}
      else if(a==="prev-create-ot"){const row=state.data.prev.find(x=>String(x.id)===String(id));dialog(`<form id="prev-ot-form"><div class="mt-dialog-head"><h2>Crear OT preventiva</h2><button class="btn" type="button" data-act="dialog-close">Cerrar</button></div><div class="mt-form">${formText("titulo","Título",{required:true,value:`Mantenimiento preventivo ${row?.plan||""}`})}<label class="wide">Descripción<textarea name="descripcion">${esc(row?.plan||"")}</textarea></label><label class="wide">Mecánicos<select name="mecanicos" multiple size="6">${optPersonal()}</select></label></div><div class="mt-dialog-actions"><button class="btn btn-primary">Crear OT</button></div></form>`);$("#prev-ot-form").onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),body={titulo:f.get("titulo"),descripcion:f.get("descripcion"),mecanicos:[...ev.currentTarget.elements.mecanicos.selectedOptions].map(o=>o.value)};try{const d=await post(`/preventivo/asignaciones/${id}/ot`,body);closeDialog();await openOrden(d.id);}catch(x){showError(x);}};}
      else if(a==="prev-done"){const date0=new Date().toISOString().slice(0,10);dialog(`<form id="prev-done-form"><div class="mt-dialog-head"><h2>Registrar service realizado</h2><button class="btn" type="button" data-act="dialog-close">Cerrar</button></div><div class="mt-form">${formText("hs","Horómetro",{type:"number",step:"0.1"})}${formText("km","Kilómetros",{type:"number",step:"0.1"})}${formText("fecha","Fecha",{type:"date",required:true,value:date0})}<label class="wide">Nota<textarea name="nota"></textarea></label></div><div class="mt-dialog-actions"><button class="btn btn-primary">Guardar</button></div></form>`);$("#prev-done-form").onsubmit=async ev=>{ev.preventDefault();const f=Object.fromEntries(new FormData(ev.currentTarget));try{await post(`/preventivo/asignaciones/${id}/realizado`,f);closeDialog();await renderPreventivo();}catch(x){showError(x);}};}
      else if(a==="prev-remove"){if(await SMG.confirmar("Quitar equipo del plan","El equipo dejará de figurar en este plan preventivo.",{ok:"Quitar",peligro:true})){await api(`/preventivo/asignaciones/${id}`,{method:"DELETE"});closeDialog();await renderPreventivo();}}
      else if(a==="prev-review"){const nota=await ask("Revisar lectura","Nota de revisión",{multilinea:true,required:false});if(nota!==null){await post(`/preventivo/lecturas/${id}/revisada`,{nota});await renderPreventivo();}}
      else if(a==="ind-filter"){state.data.desde=$("#ind-desde").value;state.data.hasta=$("#ind-hasta").value;await renderIndicadores();}
      else if(a==="ck-mod-new"){dialog(`<form id="ck-mod-form"><div class="mt-dialog-head"><h2>Agregar módulo</h2><button type="button" class="btn" data-act="dialog-close">Cerrar</button></div><div class="mt-form">${formText("nombre","Nombre",{required:true,wide:true})}<label>Capa<select name="capa"><option>MODULO</option><option>BASE</option><option>FAMILIA</option></select></label><label>Familia<select name="familia"><option></option><option>VIAL</option><option>MAQUINARIA</option><option>REMOLQUE</option></select></label></div><div class="mt-dialog-actions"><button class="btn btn-primary">Guardar módulo</button></div></form>`);$("#ck-mod-form").onsubmit=async ev=>{ev.preventDefault();try{await post("/plantilla/modulos",Object.fromEntries(new FormData(ev.currentTarget)));closeDialog();await renderConfig();}catch(x){showError(x);}};}
      else if(a==="ck-item-new"){const mid=id;dialog(`<form id="ck-item-form"><div class="mt-dialog-head"><h2>Agregar ítem</h2><button type="button" class="btn" data-act="dialog-close">Cerrar</button></div><input type="hidden" name="modulo_id" value="${esc(mid)}"><div class="mt-form">${formText("texto","Texto",{required:true,wide:true})}<label>Tipo<select name="tipo"><option>ESTADO</option><option>VIGENCIA</option></select></label><label class="wide"><span><input type="checkbox" name="opcional" value="true"> Opcional (admite N/A)</span><span><input type="checkbox" name="critico" value="true"> Crítico</span><span><input type="checkbox" name="foto_obligatoria" value="true"> Foto obligatoria</span></label></div><div class="mt-dialog-actions"><button class="btn btn-primary">Guardar ítem</button></div></form>`);$("#ck-item-form").onsubmit=async ev=>{ev.preventDefault();const f=new FormData(ev.currentTarget),body=Object.fromEntries(f);for(const k of ["opcional","critico","foto_obligatoria"])body[k]=f.has(k);try{await post("/plantilla/items",body);closeDialog();await renderConfig();}catch(x){showError(x);}};}
    } catch(err){showError(err);}
  });
  window.addEventListener("hashchange",()=>{state.otId=null;render().catch(showError);});
  render().catch(showError);
})();
